mapper.sql:
WHERE n.request_url IS NOT NULL AND n.request_url != ''
AND n.chain_code = #{chainCode}

    AND (n.chain_code LIKE CONCAT('%', #{keyword}, '%')
      OR c.chain_name LIKE CONCAT('%', #{keyword}, '%')
      OR n.request_url LIKE CONCAT('%', #{keyword}, '%')
      OR n.target_system LIKE CONCAT('%', #{keyword}, '%'))

AND COALESCE(n.interface_scope, 'UNKNOWN') = #{scope}
AND UPPER(COALESCE(n.request_method, 'GET')) = UPPER(#{method})
AND r.category = #{category}
